import time
from abc import abstractmethod, ABCMeta
from six import add_metaclass
from ta_attenuator.is_iterator import is_iterator


@add_metaclass(ABCMeta)
class FadingScenario(object):
    """Fading Scenario module"""

    def __init__(self):
        self.finished = False
        self.fading_step = None
        self.fading_interval = None
        self.fading_min = None
        self.fading_max = None

    @abstractmethod
    def get_rf_paths(self):
        """list of RF-path-addresses handled by this fading scenario"""
        return []

    @abstractmethod
    def get_attenuation_on_rf_path(self, rf_path_name):
        """
        Attenuation value (in dB or %) to be set on given RF-path-address.
        That value may be time-dependent, means: scenario may calculate it based on delay from scenario start time
        """
        return 0.0

    @abstractmethod
    def get_nearest_attenuation_timepoint(self):
        """Nearest point-in-time when scenario will set some attenuation on its RF-path"""
        return 0.0

    def is_finished(self):
        """Is fading scenario already done?"""
        return self.finished

    def _finish(self):
        self.finished = True

    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        pass

    def _calculate_attenuation(self, time_from_start):
        if self.fading_step >= 0:
            attenuation_value = int(self.fading_min + ((self.fading_step * time_from_start) / self.fading_interval))
            if attenuation_value > self.fading_max + self.fading_step:
                self._finish()
            if attenuation_value >= self.fading_max:
                attenuation_value = self.fading_max
        else:
            attenuation_value = int(self.fading_max + ((self.fading_step * time_from_start) / self.fading_interval))
            if attenuation_value < self.fading_min + self.fading_step:
                self._finish()
            if attenuation_value <= self.fading_min:
                attenuation_value = self.fading_min
        return attenuation_value


class SingleCellLinearFadingScenario(FadingScenario):
    """SingleCellLinearFadingScenario"""

    def __init__(self, faded_cell, fading_step, fading_interval, fading_min, fading_max):
        super(SingleCellLinearFadingScenario, self).__init__()
        self.faded_cell = faded_cell
        assert fading_interval[-1] == 's'
        fading_interval = float(fading_interval[:-1])
        assert fading_step[-2:] == 'db'
        fading_step = float(fading_step[:-2])
        self.fading_step, self.fading_interval = fading_step, fading_interval
        self.fading_min, self.fading_max = fading_min, fading_max

        self.t0 = time.time()
        self.nearest_attenuation_timepoint = time.time() + self.fading_interval

    def get_rf_paths(self):
        """list of RF-path-addresses handled by this fading scenario"""
        rf_paths = []
        rf_paths.extend(self.faded_cell)
        return rf_paths

    def get_attenuation_on_rf_path(self, rf_path_name):
        """
        :param rf_path_name: name of radio path to attenuate
        :return: For ex. '5 db'
        """
        return "{} db".format(self._calculate_attenuation(time.time() - self.t0))

    def get_nearest_attenuation_timepoint(self):
        """Nearest point-in-time when scenario will set some attenuation on its RF-path"""
        while self.nearest_attenuation_timepoint < time.time():
            self.nearest_attenuation_timepoint += self.fading_interval
        return self.nearest_attenuation_timepoint

    def __enter__(self):
        self.t0 = time.time()


class LinearFadingScenario(FadingScenario):
    """LinearFadingScenario"""

    # pylint: disable=too-many-instance-attributes
    def __init__(self, attenuated_cell, deattenuated_cell, fading_step, fading_interval, fading_min, fading_max):
        super(LinearFadingScenario, self).__init__()
        self.attenuated_cell, self.deattenuated_cell = attenuated_cell, deattenuated_cell
        assert fading_interval[-1] == 's'
        fading_interval = float(fading_interval[:-1])
        assert fading_step[-2:] == 'db'
        fading_step = float(fading_step[:-2])
        self.fading_step, self.fading_interval = fading_step, fading_interval
        self.fading_min, self.fading_max = fading_min, fading_max

        self.t0 = time.time()
        self.nearest_attenuation_timepoint = time.time() + self.fading_interval

    def get_rf_paths(self):
        """list of RF-path-addresses handled by this fading scenario"""
        rf_paths = []
        rf_paths.extend(self.attenuated_cell)
        rf_paths.extend(self.deattenuated_cell)
        return rf_paths

    def get_attenuation_on_rf_path(self, rf_path_name):
        """
        :param rf_path_name: name of radio path to attenuate
        :return: For ex. '5 db'
        """
        attenuation_value = self._calculate_attenuation(time.time() - self.t0)
        if rf_path_name in self.attenuated_cell:
            return "{} db".format(attenuation_value)
        deattenuation_value = float(self.fading_max) - attenuation_value + self.fading_min
        return "{} db".format(deattenuation_value)

    def get_nearest_attenuation_timepoint(self):
        """Nearest point-in-time when scenario will set some attenuation on its RF-path"""
        while self.nearest_attenuation_timepoint < time.time():
            self.nearest_attenuation_timepoint += self.fading_interval
        return self.nearest_attenuation_timepoint

    def __enter__(self):
        self.t0 = time.time()


class IncorrectGeneratorType(Exception):
    """Exception class"""
    pass


class FadingScenarioFromIterator(FadingScenario):
    """FadingScenarioFromIterator"""

    def __init__(self, scenario_iterator):
        super(FadingScenarioFromIterator, self).__init__()
        self.scenario_iterator = scenario_iterator
        self.nearest_attenuation_timepoint = time.time()
        self.last_fading_step = None
        raise Exception("Class FadingScenarioFromIterator is not fully implemented yet!")
        # super(FadingScenarioFromIterator, self).__init__()
        # if not hasattr(scenario_iterator, 'next'):
        #     raise Exception("scenario_iterator expected")

    def get_rf_paths(self):
        """list of RF-path-addresses handled by this fading scenario"""
        fading_step = self._get_fading_step()
        attenuations = fading_step['synchronous_attenuations']
        self.last_fading_step = fading_step
        return attenuations.keys()

    def get_attenuation_on_rf_path(self, rf_path_name):
        """
        Attenuation value (in dB or %) to be set on given RF-path-address.
        That value may be time-dependent, means: scenario may calculate it based on delay from scenario start time
        """
        fading_step = self._get_fading_step()
        attenuations = fading_step['synchronous_attenuations']  # TODO: may return multiple paths to attenuate
        delay = fading_step['next_step_delay']
        self._update_nearest_attenuation_timepoint(delay)
        self.last_fading_step = fading_step
        return attenuations[rf_path_name]  # TODO: so why we are handling only one?

    def _get_fading_step(self):
        try:
            fading_step = next(self.scenario_iterator)  # Python 2 & 3
        except StopIteration:
            self._finish()
            if self.last_fading_step is None:
                raise Exception("scenario_iterator has never returned anything")
            fading_step = self.last_fading_step
        return fading_step

    def _update_nearest_attenuation_timepoint(self, delay):
        self.nearest_attenuation_timepoint = time.time() + delay

    def get_nearest_attenuation_timepoint(self):
        """Nearest point-in-time when scenario will set some attenuation on its RF-path"""
        return self.nearest_attenuation_timepoint


def wrap_into_fading_scenario(scenario_iterator):
    """
    Wrapper function allowing to use iterator-based-scenario as FadingScenario instance
    """
    if isinstance(scenario_iterator, FadingScenario):
        return scenario_iterator
    if is_iterator(scenario_iterator):
        return FadingScenarioFromIterator(scenario_iterator)
    raise IncorrectGeneratorType("expected FadingScenario or iterator; not {}".format(type(scenario_iterator)))
